// Leetcode: 486 - Predict the winner
public class PredictTheWinner {
    public static boolean predictTheWinner(int[] nums) {
        int n = nums.length;
        Integer[][] dp =  new Integer[n][n];
        return solve(nums, 0, n - 1, dp) >= 0;
    }

    private static int solve(int[] nums, int left, int right, Integer[][] dp) {
        if (left == right) return nums[left];
        if (dp[left][right] != null) return dp[left][right];
        int takeLeft = nums[left] - solve(nums, left + 1, right, dp);
        int takeRight = nums[right] - solve(nums, left, right - 1, dp);
        return dp[left][right] = Math.max(takeLeft, takeRight);

    }

    public static void main(String[] args) {
        int[] nums = {1,5,233,7};
        System.out.println(predictTheWinner(nums) ? "Player 1 wins!" : "Player 2 wins!");
        nums = new int[]{1, 5, 2};
        System.out.println(predictTheWinner(nums) ? "Player 1 wins!" : "Player 2 wins!");

    }
}
